import{_ as e,o as a,c as p,am as s}from"./chunks/framework.CiF4W93w.js";const u=JSON.parse('{"title":"SpringCloud_组件基本使用_OpenFeign","description":"","frontmatter":{"title":"SpringCloud_组件基本使用_OpenFeign","excerpt":"SpringCloud_组件基本使用_OpenFeign","date":"2023-12-04 15:41:11","updated":"2023-12-04 15:41:11"},"headers":[],"relativePath":"框架/微服务&分布式/框架 SpringCloud/SpringCloud_组件基本使用_OpenFeign.md","filePath":"框架/微服务&分布式/框架 SpringCloud/SpringCloud_组件基本使用_OpenFeign.md","lastUpdated":null}'),l={name:"框架/微服务&分布式/框架 SpringCloud/SpringCloud_组件基本使用_OpenFeign.md"};function i(o,n,t,c,d,g){return a(),p("div",null,[...n[0]||(n[0]=[s(`<h3 id="_1、服务调用" tabindex="-1">1、服务调用 <a class="header-anchor" href="#_1、服务调用" aria-label="Permalink to &quot;1、服务调用&quot;">​</a></h3><h4 id="服务注册、服务发现、服务调用" tabindex="-1">服务注册、服务发现、服务调用 <a class="header-anchor" href="#服务注册、服务发现、服务调用" aria-label="Permalink to &quot;服务注册、服务发现、服务调用&quot;">​</a></h4><p>在Spring Cloud Alibaba生态系统中，服务调用的核心组件是 <strong>Nacos Discovery</strong> 和 <strong>Feign</strong>。</p><blockquote><p>Nacos Discovery</p></blockquote><p>Nacos是一个开源的服务发现和配置管理平台，它提供了服务注册与发现的功能，可以让微服务应用在注册到Nacos注册中心后，方便地发现其他服务，并实现服务之间的调用。通过Nacos Discovery，服务之间的关系和位置信息能够得到维护，实现了服务注册和服务发现。</p><blockquote><p>Feign</p></blockquote><p>Feign是一个声明式的Web服务客户端，它简化了服务调用的过程。通过在接口上添加注解，Feign能够自动构造HTTP请求并将其发送到服务提供方。在Spring Cloud Alibaba中，Feign与Nacos Discovery集成，可以使用Feign来发起服务调用，而Nacos Discovery则用于服务的注册和发现。</p><h4 id="微服务间的调用方式" tabindex="-1">微服务间的调用方式 <a class="header-anchor" href="#微服务间的调用方式" aria-label="Permalink to &quot;微服务间的调用方式&quot;">​</a></h4><blockquote><p>微服务调用</p></blockquote><p>微服务之间的通信方式常见的方式有两种：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RPC 代表：dubbo  </span></span>
<span class="line"><span>HTTP 代表：SpringCloud</span></span></code></pre></div><p>在微服务架构中，最常见的场景就是微服务间的相互调用。</p><p>在 SpringCloud 中，默认是使用 HTTP 来进行微服务的通信，微服务间的相互调用方式主要有<code>RestTemplate</code>、<code>Feign</code> 、和<code>OpenFeign</code></p><blockquote><p>RestTemplate</p></blockquote><p>RestTemplate 是从 Spring3.0 开始支持的一个 http 请求工具，这个请求工具是 Spring 自带的</p><p>RestTemplate 提供了常见的 REST 请求方法模板，如 GET、POST、PUT、DELETE 请求以及一些通用的请求执行方法 exchange 和 execute 方法</p><blockquote><p>Feign</p></blockquote><p>Feign 是 Spring Cloud 组件中的一个<code>声明式</code>的<code>轻量级 RESTful 的 HTTP 服务客户端</code></p><p>Feign 内置了 Ribbon，用来做<code>客户端负载均衡</code>，去调用服务注册中心的服务；</p><blockquote><p>OpenFeign</p></blockquote><p>OpenFeign 是 Spring Cloud 在 Feign 的基础上支持 SpringMVC 的注解，如 @RequesMapping 等等。</p><p>OpenFeign 的 @FeignClient 可以解析 SpringMVC 的 @RequestMapping 注解下的接口，并通过动态代理的方式产生实现类，实现类中做负载均衡并调用其他服务</p><blockquote><p>OpenFeign 和 Feign 组件的区别和关联</p></blockquote><p>OpenFeign 是 Feign 的增强版，它是 Spring Cloud 对 Feign 进行了扩展和优化的结果。虽然两者有关联，但在一些功能和使用上存在一些区别。</p><p><strong>Feign:</strong></p><ul><li>Feign 是一个声明式的Web服务客户端，用于简化服务调用的过程。</li><li>它基于接口定义，通过添加注解，可以轻松地发起HTTP请求。</li><li>在原始的 Spring Cloud 中，Feign 的默认实现不支持 Spring MVC 注解，因此使用起来有一些限制。</li></ul><p><strong>OpenFeign:</strong></p><ul><li>OpenFeign 是对 Feign 的增强，它引入了对 Spring MVC 注解的支持，使得 Feign 在使用上更加灵活。</li><li>OpenFeign 提供了更丰富的功能，例如继承性、支持 Spring Cloud Contract、支持多部分请求和响应等。</li><li>OpenFeign 可以通过 <code>@FeignClient</code> 注解的 <code>contextId</code> 属性来实现多个 Feign 客户端实例之间的隔离。</li></ul><p>在Spring Cloud项目中，如果你使用 <code>@FeignClient</code> 注解，实际上默认是使用的 OpenFeign。</p><p>Spring Cloud 在 Hoxton.RELEASE 版本之后<strong>默认使用 OpenFeign，而不是原始的 Feign。</strong></p><p>关于使用 <code>@FeignClient</code> 注解创建 Feign 客户端的例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@FeignClient(name = &quot;example-service&quot;, url = &quot;http://example.com&quot;)</span></span>
<span class="line"><span>public interface ExampleFeignClient {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @GetMapping(&quot;/hello&quot;)</span></span>
<span class="line"><span>    String hello();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在上述例子中，<code>@FeignClient</code> 注解指定了服务的名称和URL，<code>ExampleFeignClient</code> 接口定义了服务调用的契约。通过添加 <code>@GetMapping</code> 注解，实现了对服务提供者的 <code>/hello</code> 接口的调用。</p><p>总体而言，OpenFeign 是对 Feign 的增强版本，提供了更多的功能和更好的灵活性，而在 Spring Cloud 中，我们常常通过 <code>@FeignClient</code> 注解来使用 OpenFeign。</p><h3 id="_2、openfeign-的使用" tabindex="-1">2、OpenFeign 的使用 <a class="header-anchor" href="#_2、openfeign-的使用" aria-label="Permalink to &quot;2、OpenFeign 的使用&quot;">​</a></h3><h4 id="feignclient的基本使用方法" tabindex="-1"><code>@FeignClient</code>的基本使用方法 <a class="header-anchor" href="#feignclient的基本使用方法" aria-label="Permalink to &quot;\`@FeignClient\`的基本使用方法&quot;">​</a></h4><p><code>@FeignClient</code> 是 Spring Cloud 中用于声明式REST客户端的注解。通过使用该注解，可以定义一个接口，而不需要实现该接口，Spring Cloud会在运行时自动生成该接口的实现类，用于发起服务间的HTTP请求。</p><p>以下是<code>@FeignClient</code>的基本使用方法：</p><blockquote><p><strong>简单使用：</strong></p></blockquote><p>在一个接口上添加 <code>@FeignClient</code> 注解，并指定要调用的服务名称</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import org.springframework.cloud.openfeign.FeignClient;</span></span>
<span class="line"><span>import org.springframework.web.bind.annotation.GetMapping;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@FeignClient(name = &quot;example-service&quot;)</span></span>
<span class="line"><span>public interface ExampleFeignClient {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @GetMapping(&quot;/hello&quot;)</span></span>
<span class="line"><span>    String hello();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在上述例子中，<code>ExampleFeignClient</code> 接口用于调用名为 &quot;example-service&quot; 的微服务，其中 <code>@GetMapping(&quot;/hello&quot;)</code> 定义了调用服务的路径。</p><blockquote><p>指定 URL</p></blockquote><p>可以通过 <code>url</code> 属性指定服务的URL，而不是通过服务名称进行调用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@FeignClient(name = &quot;example-service&quot;, url = &quot;http://example.com&quot;)</span></span>
<span class="line"><span>public interface ExampleFeignClient {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @GetMapping(&quot;/hello&quot;)</span></span>
<span class="line"><span>    String hello();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个例子中，服务的URL被硬编码为 &quot;<a href="http://example.com" target="_blank" rel="noreferrer">http://example.com</a>&quot;。</p><blockquote><p><strong>指定Fallback</strong></p></blockquote><p>可以通过 <code>fallback</code> 属性指定一个实现了 <code>ExampleFeignClient</code> 接口的类，作为调用失败时的降级处理。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@FeignClient(name = &quot;example-service&quot;, fallback = ExampleFeignClientFallback.class)</span></span>
<span class="line"><span>public interface ExampleFeignClient {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @GetMapping(&quot;/hello&quot;)</span></span>
<span class="line"><span>    String hello();</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>public class ExampleFeignClientFallback implements ExampleFeignClient {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Override</span></span>
<span class="line"><span>    public String hello() {</span></span>
<span class="line"><span>        return &quot;Fallback Hello&quot;;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个例子中，当调用服务失败时，会执行 <code>ExampleFeignClientFallback</code> 中的逻辑。</p><blockquote><p><strong>指定Decoder和Encoder</strong></p></blockquote><p>可以通过 <code>decoder</code> 和 <code>encoder</code> 属性指定自定义的解码器和编码器。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@FeignClient(name = &quot;example-service&quot;, decoder = MyDecoder.class, encoder = MyEncoder.class)</span></span>
<span class="line"><span>public interface ExampleFeignClient {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @GetMapping(&quot;/hello&quot;)</span></span>
<span class="line"><span>    String hello();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个例子中，<code>MyDecoder</code> 和 <code>MyEncoder</code> 分别是自定义的解码器和编码器。</p><p>这些是 <code>@FeignClient</code> 注解的基本用法，通过灵活使用这些属性，可以实现更多定制化的服务调用配置。</p><p>to be continued....</p><hr><p>参考</p><ul><li><a href="https://blog.csdn.net/IT__learning/article/details/116349843" target="_blank" rel="noreferrer">https://blog.csdn.net/IT__learning/article/details/116349843</a></li></ul>`,59)])])}const b=e(l,[["render",i]]);export{u as __pageData,b as default};
